+		assert_eq!(payload["temperature"], 0.5, "temperature for {model}");
+		assert_eq!(payload["top_p"], 0.9, "top_p for {model}");
+		assert_eq!(payload["stop"], json!(["END"]), "stop for {model}");
+	}
